import csv
import io

def parse_csv(raw_csv: str):
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    records = list(reader)

    if not records:
        return {"columns": [], "rows": []}

    if records[0]:
        records[0][0] = records[0][0].lstrip("\ufeff")

    header_index = None
    for i, row in enumerate(records):
        if len(row) >= 8 and sum(bool(cell.strip()) for cell in row) >= 2:
            header_index = i
            break

    if header_index is None:
        for i, row in enumerate(records):
            if any(cell.strip() for cell in row):
                header_index = i
                break

    if header_index is None:
        return {"columns": [], "rows": records}

    columns = records[header_index][:]
    rows = records[header_index + 1:]
    width = max([len(columns)] + [len(row) for row in rows])

    existing = set(columns)
    while len(columns) < width:
        index = len(columns) + 1
        name = "column_" + str(index)
        while name in existing:
            name += "_"
        columns.append(name)
        existing.add(name)

    rows = [row + [""] * (width - len(row)) for row in rows]
    return {"columns": columns, "rows": rows}
